package edu.pe.cibertec.saibm.usuario.infrastructure.messaging; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import edu.pe.cibertec.saibm.usuario.infrastructure.persistence.*; @Component public class UserOutboxPublisher {private final UserOutboxRepository outbox;private final RabbitTemplate rabbit;public UserOutboxPublisher(UserOutboxRepository o,RabbitTemplate r){outbox=o;rabbit=r;}@Scheduled(fixedDelayString="${usuario.outbox.delay-ms:500}")@Transactional public void publish(){for(var e:outbox.pending(PageRequest.of(0,50))){rabbit.convertAndSend(UserRabbitConfig.EXCHANGE,e.eventType(),e.payloadJson());e.published();outbox.save(e);}}}
